SELECT ID, CASE WHEN RNK <= (1/4) * TOTAL_COUNT THEN 'CRITICAL' WHEN RNK <= (1/2) * TOTAL_COUNT THEN 'HIGH' WHEN RNK <= (3/4) * TOTAL_COUNT THEN 'MEDIUM' ELSE 'LOW' END AS COLONY_NAME
FROM (SELECT ID, SIZE_OF_COLONY, RANK() OVER (ORDER BY SIZE_OF_COLONY DESC) AS RNK, COUNT(*) OVER () AS TOTAL_COUNT FROM ECOLI_DATA) SUB
ORDER BY ID ASC;